def expanded_ids(text):
    found=set()
    for m in re.finditer(r'\b(P\d+[A-Z]*\.)(\d+)(?:[–-](?:P\d+[A-Z]*\.)?(\d+))?',text):
        prefix,start,end=m.groups();start=int(start)
        for n in range(start,int(end)+1 if end else start+1):found.add(prefix+str(n))
    return found
